/* ---- js/export.js ---- */
// export.js - builds the Markdown export of the watchlist and its recommendations (DOM-free, deterministic).
// Same input always yields the same output: no timestamps other than dataset metadata; stable ordering.



/** Escape Markdown-significant characters in inline text and collapse newlines. */
function mdEscape(value) {
  return String(value ?? '')
    .replace(/\s*[\r\n]+\s*/g, ' ')
    .replace(/([\\`*_{}\[\]<>#|])/g, '\\$1');
}

function label(list, id) {
  const hit = (list || []).find((x) => x.id === id);
  return hit ? hit.label : String(id);
}

/**
 * @param {{trends:object[], recommendations:object[], watchlist:string[]|Set<string>, meta?:object, taxonomy?:object}} input
 * @returns {string} Markdown
 */
function watchlistToMarkdown({ trends, recommendations, watchlist, meta, taxonomy }) {
  const tax = taxonomy || {};
  const watched = watchlist instanceof Set ? watchlist : new Set(watchlist || []);
  const picked = trends
    .filter((t) => watched.has(t.id))
    .sort((a, b) => String(a.title).localeCompare(String(b.title), 'en', { sensitivity: 'base' }) || String(a.id).localeCompare(String(b.id)));

  const out = [];
  out.push('# IAM Trend Radar watchlist', '');
  if (meta) out.push(`Dataset ${mdEscape(meta.datasetVersion)} (last updated ${mdEscape(meta.lastUpdated)}). ${mdEscape(meta.disclaimer || '')}`.trim(), '');
  if (picked.length === 0) {
    out.push('_No trends on the watchlist._', '');
    return out.join('\n');
  }

  for (const t of picked) {
    out.push(`## ${mdEscape(t.title)}`, '');
    out.push(`- Maturity: ${mdEscape(label(tax.maturity, t.maturity))}`);
    out.push(`- Impact: ${mdEscape(label(tax.impact, t.impact))}`);
    out.push(`- Momentum: ${mdEscape(label(tax.momentum, t.momentum))}`);
    if (t.needsVerification) out.push(`- Needs verification: ${mdEscape(t.verificationNotes)}`);
    out.push('', mdEscape(t.summary), '');
    if (t.sources && t.sources.length) {
      out.push('Sources:', '');
      for (const s of t.sources) {
        out.push(`- [${mdEscape(s.title)}](${encodeMdUrl(s.url)}) (${mdEscape(s.publisher)}, ${mdEscape(s.type)})`);
      }
      out.push('');
    }
    const recs = sortRecs(recommendations.filter((r) => (r.trendIds || []).includes(t.id)), 'priority');
    if (recs.length) {
      out.push('### Recommendations', '');
      for (const r of recs) {
        out.push(`#### ${mdEscape(r.title)}`, '');
        out.push(`- Horizon: ${mdEscape(label(tax.horizon, r.horizon))}`);
        out.push(`- Effort: ${mdEscape(label(tax.effort, r.effort))}`);
        out.push(`- Impact: ${mdEscape(label(tax.impact, r.impact))}`);
        out.push('- Steps:');
        (r.steps || []).forEach((step, i) => out.push(`  ${i + 1}. ${mdEscape(step)}`));
        out.push('');
      }
    }
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').replace(/\n*$/, '\n');
}

function encodeMdUrl(url) {
  // encodeURIComponent leaves ( and ) alone, which would end the Markdown link early; encode them explicitly.
  return String(url ?? '').replace(/[()\s<>]/g, (c) => (c === '(' ? '%28' : c === ')' ? '%29' : encodeURIComponent(c)));
}

/* ---- js/store.js ---- */
// store.js - data loading (window.IAM_DATA bundle first, fetch fallback) and safe localStorage state.
// Every storage access is wrapped in try/catch; the app keeps working in memory if storage is unavailable.



const WATCH_KEY = 'iamradar.watchlist.v1';
const FILTER_KEY = 'iamradar.filters.v1';

const state = {
  meta: null,
  taxonomy: null,
  trends: [],
  recommendations: [],
  trendMap: new Map(),
  recMap: new Map(),
  watch: new Set(),
  filters: defaultFilters(),
  recFilters: defaultRecFilters(),
  storageOk: true
};

function storageGet(key) {
  try { return globalThis.localStorage.getItem(key); } catch { state.storageOk = false; return null; }
}
function storageSet(key, value) {
  try { globalThis.localStorage.setItem(key, value); return true; } catch { state.storageOk = false; return false; }
}

async function fetchJson(name) {
  const res = await fetch(`data/${name}.json`);
  if (!res.ok) throw new Error(`Could not load data/${name}.json (HTTP ${res.status})`);
  return res.json();
}

/** Loads the dataset. Throws an Error with a user-facing message on failure. */
async function loadData() {
  let raw = globalThis.IAM_DATA;
  if (!raw) {
    try {
      const [meta, taxonomy, trends, recommendations] = await Promise.all(['meta', 'taxonomy', 'trends', 'recommendations'].map(fetchJson));
      raw = { meta, taxonomy, trends, recommendations };
    } catch (e) {
      throw new Error(`The data could not be loaded (${e.message}).`);
    }
  }
  if (!raw || !Array.isArray(raw.trends) || !Array.isArray(raw.recommendations) || !raw.taxonomy || !raw.meta) {
    throw new Error('The data is incomplete or malformed.');
  }
  state.meta = raw.meta;
  state.taxonomy = raw.taxonomy;
  state.trends = raw.trends;
  state.recommendations = raw.recommendations;
  state.trendMap = new Map(raw.trends.map((t) => [t.id, t]));
  state.recMap = new Map(raw.recommendations.map((r) => [r.id, r]));
  loadWatchlist();
  loadFilters();
}

function loadWatchlist() {
  state.watch = new Set();
  const raw = storageGet(WATCH_KEY);
  if (!raw) return;
  try {
    const arr = JSON.parse(raw);
    if (Array.isArray(arr)) arr.forEach((id) => { if (state.trendMap.has(id)) state.watch.add(id); });
  } catch { /* ignore corrupt value */ }
}

function saveWatchlist() { storageSet(WATCH_KEY, JSON.stringify([...state.watch])); }

function isWatched(id) { return state.watch.has(id); }

/** Toggles a trend in the watchlist; returns the new watched state. */
function toggleWatch(id) {
  if (!state.trendMap.has(id)) return false;
  if (state.watch.has(id)) state.watch.delete(id); else state.watch.add(id);
  saveWatchlist();
  return state.watch.has(id);
}

function clearWatchlist() {
  state.watch = new Set();
  saveWatchlist();
}

function loadFilters() {
  const raw = storageGet(FILTER_KEY);
  if (!raw) return;
  try {
    const f = JSON.parse(raw);
    if (!f || typeof f !== 'object') return;
    const tx = state.taxonomy;
    const ok = (list, v) => typeof v === 'string' && (v === '' || tx[list].some((x) => x.id === v));
    const next = defaultFilters();
    if (ok('categories', f.category)) next.category = f.category;
    if (ok('maturity', f.maturity)) next.maturity = f.maturity;
    if (ok('impact', f.impact)) next.impact = f.impact;
    if (ok('momentum', f.momentum)) next.momentum = f.momentum;
    if (typeof f.text === 'string') next.text = f.text.slice(0, 200);
    if (f.watchOnly === true) next.watchOnly = true;
    if (TREND_SORTS.includes(f.sort)) next.sort = f.sort;
    state.filters = next;
  } catch { /* ignore corrupt value */ }
}

function saveFilters() { storageSet(FILTER_KEY, JSON.stringify(state.filters)); }

function resetFilters() {
  state.filters = defaultFilters();
  saveFilters();
}

/** Rendering context shared by the views and the ui.js card helpers. */
function makeCtx() {
  return {
    taxonomy: state.taxonomy,
    isWatched,
    isStale: (d) => isStale(d),
    trendById: (id) => state.trendMap.get(id),
    recById: (id) => state.recMap.get(id),
    score: priorityScore
  };
}

